create table public.companies(id uuid primary key default gen_random_uuid(), name text not null, plan text not null check(plan in ('essential','pro')), regions text[] not null, active boolean default true, expires_at timestamptz, check((plan='essential' and cardinality(regions)=7) or (plan='pro' and cardinality(regions)=14)));
create table public.profiles(id uuid primary key references auth.users on delete cascade, company_id uuid references companies, role text not null check(role in ('super_admin','client')));
create table public.listings(id uuid primary key default gen_random_uuid(), url text unique not null, title text not null, description text, region text, kind text not null default 'immobilier', seller text default 'indéterminé', price numeric, previous_price numeric, source text, score integer check(score between 0 and 100), analysis text, analysis_mode text, suggested_message text, first_seen timestamptz default now(), last_seen timestamptz default now());
create table public.price_observations(id bigint generated always as identity primary key, listing_id uuid references listings on delete cascade, price numeric not null, observed_at timestamptz default now());
create table public.prospects(id uuid primary key default gen_random_uuid(), company_id uuid not null references companies, listing_id uuid not null references listings, title text not null, stage text default 'Nouveau', notes text default '', followup date, unique(company_id,listing_id));
create table public.sources(id uuid primary key default gen_random_uuid(), name text unique, status text default 'à valider');
insert into sources(name,status) values ('Brave Search','clé requise'),('Expat-Dakar','à valider'),('CoinAfrique','à valider'),('Loger Sénégal','à valider'),('Keur-Immo','à valider'),('Diaspora.immo','à valider'),('Facebook Marketplace','manuel uniquement');
create table public.collection_runs(id uuid primary key default gen_random_uuid(), company_id uuid references companies, status text not null, count integer default 0, created_at timestamptz default now());
create function public.my_company() returns uuid language sql stable security definer set search_path=public as $$ select company_id from profiles where id=auth.uid() $$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce((select role='super_admin' from profiles where id=auth.uid()),false) $$;
create function public.has_plan(p text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from companies where id=my_company() and active and (expires_at is null or expires_at>now()) and (plan=p or (p='essential' and plan='pro'))) $$;
create function public.can_read_listing(r text,k text) returns boolean language sql stable security definer set search_path=public as $$ select is_admin() or exists(select 1 from companies where id=my_company() and active and (expires_at is null or expires_at>now()) and ((plan='pro') or (k='immobilier' and r=any(regions)))) $$;
create function public.enforce_seats() returns trigger language plpgsql security definer set search_path=public as $$ declare lim integer; begin if new.company_id is null then if new.role<>'super_admin' then raise exception 'Entreprise obligatoire'; end if; return new; end if; select case plan when 'essential' then 1 else 4 end into lim from companies where id=new.company_id for update; if (select count(*) from profiles where company_id=new.company_id and id<>new.id)>=lim then raise exception 'Quota utilisateurs atteint'; end if; return new; end $$;
create trigger profile_seats before insert or update on profiles for each row execute function enforce_seats();
create function public.check_downgrade() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.plan='essential' and (select count(*) from profiles where company_id=new.id)>1 then raise exception 'Retirer les comptes supplémentaires avant changement de pack'; end if; return new; end $$;
create trigger company_downgrade before update on companies for each row execute function check_downgrade();
 alter table companies enable row level security; alter table profiles enable row level security; alter table listings enable row level security; alter table price_observations enable row level security; alter table prospects enable row level security; alter table sources enable row level security; alter table collection_runs enable row level security;
create policy company_read on companies for select to authenticated using(id=my_company() or is_admin());
create policy profile_read on profiles for select to authenticated using(id=auth.uid() or is_admin());
create policy listings_read on listings for select to authenticated using(can_read_listing(region,kind));
create policy observations_read on price_observations for select to authenticated using(exists(select 1 from listings where id=listing_id));
create policy prospects_read on prospects for select to authenticated using(company_id=my_company() and has_plan('pro'));
create policy prospects_insert on prospects for insert to authenticated with check(company_id=my_company() and has_plan('pro') and exists(select 1 from listings where id=listing_id));
create policy prospects_update on prospects for update to authenticated using(company_id=my_company() and has_plan('pro')) with check(company_id=my_company() and has_plan('pro') and exists(select 1 from listings where id=listing_id));
create policy sources_read on sources for select to authenticated using(has_plan('essential') or is_admin());
create policy runs_read on collection_runs for select to authenticated using(company_id=my_company() or is_admin());
-- Atomic quota reservation, service-role only.
create function public.reserve_run(c uuid, lim integer) returns uuid language plpgsql security definer set search_path=public as $$ declare result uuid; begin perform pg_advisory_xact_lock(hashtext(coalesce(c::text,'global'))); if (select count(*) from collection_runs where company_id is not distinct from c and created_at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC')>=lim then return null; end if; insert into collection_runs(company_id,status) values(c,'running') returning id into result; return result; end $$;
revoke all on function public.reserve_run(uuid,integer) from public,anon,authenticated; grant execute on function public.reserve_run(uuid,integer) to service_role;
